#!/usr/bin/env bash
# Contract for tests/check_pr_commit_declarations.sh: the gate is the only
# thing standing between a declaration-less commit message and an upstream PR
# (PR #1010 shipped two such commits unnoticed), so its exit codes are pinned
# here.
#
# Every case is built in a throwaway repository from commit-tree and mktree
# objects, so the run depends on no ref, remote or worktree of the host checkout
# and leaves nothing behind to prune. Same shape as
# tests/check_pr_commit_claims_test.sh.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'no git checkout; run from the repo root\n' >&2
    exit 1
}
gate=$root/tests/check_pr_commit_declarations.sh
if [ ! -f "$gate" ]; then
    printf 'gate missing: %s\n' "$gate" >&2
    exit 1
fi

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp while native
# git.exe maps that name elsewhere, so a sandbox built there can be invisible
# to the shell that created it. Same reasoning as the claims self-test.
tmpbase=/tmp
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -u "$USERPROFILE")
fi
tmp=$(mktemp -d "$tmpbase/pime-commit-decls-selftest.XXXXXX")
repo=$tmp/repo
trap 'rm -rf "$tmp"' EXIT

export GIT_AUTHOR_NAME=selftest GIT_AUTHOR_EMAIL=selftest@example.invalid
export GIT_COMMITTER_NAME=selftest GIT_COMMITTER_EMAIL=selftest@example.invalid

failures=0

# expect <want-code> <name> <branch-or-empty>
expect() {
    local want=$1 name=$2 br=$3 rc
    if [ -n "$br" ]; then
        ( cd "$repo" && bash "$gate" "$br" ) >/dev/null 2>&1
    else
        ( cd "$repo" && bash "$gate" ) >/dev/null 2>&1
    fi
    rc=$?
    if [ "$rc" -eq "$want" ]; then
        printf 'ok    %s\n' "$name"
    else
        printf 'FAIL  %s (want %s, got %s)\n' "$name" "$want" "$rc"
        failures=$((failures + 1))
    fi
}

git init -q "$repo" || { printf 'sandbox git init failed\n' >&2; exit 1; }

blob=$(printf 'value = 1\n' | git -C "$repo" hash-object -w --stdin)
testblob=$(printf 'def test_selftest():\n    pass\n' | git -C "$repo" hash-object -w --stdin)
git -C "$repo" remote add product https://github.com/EasyIME/PIME.git
base_tree=$(printf '100644 blob %s\tREADME.md\n' "$blob" | git -C "$repo" mktree)
tests_sub=$(printf '100644 blob %s\ttest_selftest.py\n' "$testblob" | git -C "$repo" mktree)
product_tree=$(printf '100644 blob %s\tREADME.md\n' "$blob" | git -C "$repo" mktree)
with_test_tree=$(printf '100644 blob %s\tREADME.md\n040000 tree %s\ttests\n' \
    "$blob" "$tests_sub" | git -C "$repo" mktree)

commit_of() { # <tree> <message> -> sha
    printf '%s\n' "$2" | git -C "$repo" commit-tree "$1" -p "$base"
}

base=$(printf 'initial\n' | git -C "$repo" commit-tree "$base_tree")
git -C "$repo" update-ref refs/remotes/product/master "$base"
git -C "$repo" update-ref refs/heads/master "$base"

# 1. Integration and local record branch names skip whatever they point at.
git -C "$repo" update-ref refs/heads/local/linux-master \
    "$(commit_of "$product_tree" 'docs: harness note with no declaration')"
expect 125 'integration branch name skips' local/linux-master

# 2. The autonomous form on its own line passes.
git -C "$repo" update-ref refs/heads/selftest/autonomous \
    "$(commit_of "$product_tree" 'fix(python): stop the tool dropping a value

Consult every return instead of the last one.

Fully generated by omp (model) without human intervention.')"
expect 0 'autonomous declaration passes' selftest/autonomous

# 3. The supervised form, wrapped across two lines exactly as the standing
#    rules write it, still counts: the fold is what redding it would punish.
git -C "$repo" update-ref refs/heads/selftest/wrapped \
    "$(commit_of "$product_tree" 'fix(python): stop the tool dropping a value

Consult every return instead of the last one.

Architecture and design by someone. Implementation generated with AI
assistance from omp (model).')"
expect 0 'wrapped supervised declaration passes' selftest/wrapped

# 4. The defect itself: a product commit whose message carries no declaration,
#    the shape PR #1010 shipped.
git -C "$repo" update-ref refs/heads/selftest/silent \
    "$(commit_of "$product_tree" 'fix(python): match C struct layouts

The hand-written mirrors drifted; realign all four.')"
expect 1 'commit without a declaration fails' selftest/silent

# 5. A commit that carries tests/ is judged too: the declaration is per-message,
#    not per-product-diff, so a test commit stays silent about its authorship.
git -C "$repo" update-ref refs/heads/selftest/silent-test \
    "$(commit_of "$with_test_tree" 'test(python): drive the suite with real data

Assemble the shared directory from the pinned submodule.')"
expect 1 'test commit without a declaration fails' selftest/silent-test

# 6. A ref that is not a commit is not applicable, and neither is a detached
#    HEAD with no argument.
expect 125 'non-commit ref skips' "$blob"
git -C "$repo" update-ref HEAD "$(git -C "$repo" rev-parse refs/heads/selftest/autonomous)"
expect 125 'detached HEAD without argument skips' ''

# 7. Without an EasyIME/PIME remote there is no product base to judge against.
git -C "$repo" remote set-url product https://github.com/example/other.git
git -C "$repo" update-ref refs/remotes/product/master "$base"
expect 125 'no product remote skips' selftest/silent

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
